  "privWhat1": "عند إنشاء حساب، نستخدم بريدك الإلكتروني ومعرّف الحساب وسجلات المصادقة بكلمة المرور وحالة التحقق لتقديم حسابك وحمايته. يتعامل مزوّد المصادقة مع كلمات المرور على شكل تجزئات آمنة؛ ولا يخزّن Cook كلمات مرور قابلة للقراءة. نخزّن تخطيط مطبخك واللغة المختارة والمظهر ووحدات القياس لاستعادة إعداداتك على جميع أجهزتك. يلزم بريد إلكتروني وكلمة مرور لإنشاء حساب؛ ويمكنك تصفّح الوصفات بدونه.",
  "privWhat2": "معالجة بيانات الحساب والإعدادات ضرورية لتقديم خدمة الحساب التي تطلبها (المادة 6(1)(ب) من اللائحة العامة لحماية البيانات GDPR). قد تُعالَج سجلات محدودة للأمان ومنع إساءة الاستخدام استنادًا إلى المصالح المشروعة (المادة 6(1)(و))، في حدود الضرورة وبعد الموازنة. رسائل التحقق وإعادة تعيين كلمة المرور رسائل خدمة وليست تسويقًا. لا تضيف ميزة الحساب أي إعلانات أو تحليلات.",
  "privStorage1": "يستخدم Cook ‏sessionStorage لنقل مطبخك وتقدّمك في الطهي واختياراتك بين الصفحات في علامة التبويب نفسها. عند تسجيل الدخول، يحتفظ أيضًا بجلسة المصادقة الخاصة بك. يمسح المتصفح ذلك عادةً عند انتهاء جلسة علامة التبويب، لكن استعادة الجلسات في المتصفح قد تحتفظ به. يؤدي تسجيل الخروج إلى مسح بيانات Cook في علامة التبويب. يُحفظ إغلاق إشعار التخزين في تلك العلامة فقط. لا تضع البرامج النصية الخاصة بـ Cook ملفات تعريف الارتباط. قد يكون لدى مزودي الاستضافة أو الخدمات معالجة أمنية خاصة بهم يجب توثيقها قبل الإطلاق.",
  "privStorage2": "زر «حسنًا» وزر الإغلاق في إشعار التخزين يغلقان الإشعار فقط. ولا يسمحان بالتحليلات أو الإعلانات أو أي تتبّع اختياري آخر. أي تخزين غير ضروري في المستقبل سيتطلب اختيارًا منفصلًا قبل بدئه، مع رفض وسحب بالسهولة نفسها.",
  "privOther1": "تطلب ميزة الصوت الحالية في قائمة الوصفات من country.is دولة تقريبية بناءً على عنوان IP الخاص بك لاختيار لغة التعرّف على الكلام. إذا استخدمت التعرّف عبر الميكروفون، فقد يرسل متصفحك الصوت إلى مزوّد خدمة التعرّف على الكلام الخاص به. يمكنك أيضًا كتابة المكوّنات. يجب مراجعة هؤلاء المزوّدين وسياساتهم والأساس القانوني لهذه الميزات قبل الإطلاق العام.",
  "privProviders1": "مزوّد الحسابات المخطط له: Supabase (‏PostgreSQL ومصادقة مُدارة)، مع منطقة قاعدة بيانات مختارة في الاتحاد الأوروبي. مزوّد البريد الإلكتروني: [المزوّد]. استضافة الموقع: [المزوّد]. يجب على المشغّل تأكيد المزوّدين الفعليين واتفاقيات المعالجة والمعالجين الفرعيين ومواقع السجلات وأي عمليات نقل خارج المنطقة الاقتصادية الأوروبية. لا تستبعد منطقة قاعدة بيانات في الاتحاد الأوروبي بحد ذاتها عمليات النقل الدولية. عند الاقتضاء، حدّد قرار الملاءمة أو الضمانات التعاقدية المعمول بها وكيفية الحصول على نسخة منها.",
  "privRetention1": "تُحفظ إعدادات الحساب ما دام حسابك نشطًا. يمكنك طلب الحذف عبر جهة اتصال الخصوصية المذكورة أعلاه. قبل الإطلاق، يجب على المشغّل تحديد آلية الرد على طلبات الحذف، وانتهاء صلاحية الحسابات غير المُتحقق منها، ومدد الاحتفاظ بسجلات الأمان والنسخ الاحتياطية. قد تبقى البيانات المحذوفة في نسخ احتياطية مقيّدة الوصول حتى انتهاء مدة الاحتفاظ الموثّقة.",
  "privRights1": "بحسب الشروط المعمول بها، يمكنك طلب الوصول أو التصحيح أو الحذف أو التقييد أو قابلية النقل، أو الاعتراض على المعالجة القائمة على المصلحة المشروعة. تواصل مع المشغّل المذكور أعلاه؛ يُرد على الطلبات عادةً خلال شهر واحد، مع توضيح أي تمديد قانوني. يمكنك تقديم شكوى إلى السلطة الرقابية، ومنها هيئة NAIH المجرية على naih.hu. لا يستخدم Cook إعدادات الحساب لاتخاذ قرارات آلية ذات آثار قانونية أو آثار مماثلة مهمة.",
